// These fixtures are generated by the installed systemd version; they do not
// require a running journald or depend on journal.Enabled(). Skip only when the
// fixture-generation executable is unavailable.
func journalRemote(t *testing.T) string {
	t.Helper()
	for _, candidate := range []string{"/usr/lib/systemd/systemd-journal-remote", "/lib/systemd/systemd-journal-remote", "systemd-journal-remote"} {
		if path, err := exec.LookPath(candidate); err == nil {
			return path
		}
	}
	t.Skip("install systemd-journal-remote to run native directory regressions")
	return ""
}

func appendJournalRecords(t *testing.T, remote, dir, unit string, records ...int) {
	t.Helper()
	var export strings.Builder
	for _, n := range records {
		fmt.Fprintf(&export, "__REALTIME_TIMESTAMP=%d\n__MONOTONIC_TIMESTAMP=%d\n_BOOT_ID=11111111111111111111111111111111\n_MACHINE_ID=22222222222222222222222222222222\n_HOSTNAME=journal-regression\n_SYSTEMD_UNIT=%s\nMESSAGE=record-%d\n\n",
			1700000000000000+n, 1000000+n, unit, n)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, remote, "--output="+filepath.Join(dir, "remote-fixture.journal"), "--split-mode=none", "-")
	cmd.Stdin = strings.NewReader(export.String())
	output, err := cmd.CombinedOutput()
	require.NoError(t, err, "journal fixture writer: %s", output)
}

func nativeMessages(t *testing.T, tailer *tailer, reader journalReader, count int) []string {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	var messages []string
	for len(messages) < count {
		if ctx.Err() != nil {
			t.Fatalf("timed out reading native journal: messages=%v", messages)
		}
		n, err := reader.Next()
		require.NoError(t, err)
		if n == 0 {
			require.NoError(t, tailer.waitForNewJournalEntries(ctx, reader))
			continue
		}
		entry, err := reader.GetEntry()
		require.NoError(t, err)
		messages = append(messages, entry.Fields[sdjournal.SD_JOURNAL_FIELD_MESSAGE])
	}
	return messages
}

func TestNativeJournalLiveRecovery(t *testing.T) {
	remote := journalRemote(t)
	for _, tc := range []struct {
		name, initialUnit string
		initial           []int
	}{
		{"nonempty", "target.service", []int{1, 2, 3}},
		{"zero-matches", "other.service", []int{1, 2, 3}},
		{"empty-directory", "", nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			if len(tc.initial) > 0 {
				appendJournalRecords(t, remote, dir, tc.initialUnit, tc.initial...)
			}
			runtime.LockOSThread()
			defer runtime.UnlockOSThread()
			tailer := testTailer(t)
			tailer.journalPath = dir
			tailer.matches = []string{"_SYSTEMD_UNIT=target.service"}
			reader, err := tailer.openJournal(journalOpenModeRecover)
			require.NoError(t, err)
			defer tailer.closeJournal(reader)
			// Initialize notifications before writing. Wait statuses, including
			// INVALIDATE and NOP, must all return to Next without repositioning.
			require.GreaterOrEqual(t, reader.Wait(0), 0)
			// Positioning is complete before the writer starts; no guessed sleep.
			appendJournalRecords(t, remote, dir, "target.service", 4, 5, 6)
			require.Equal(t, []string{"record-4", "record-5", "record-6"}, nativeMessages(t, tailer, reader, 3))
			n, err := reader.Next()
			require.NoError(t, err)
			require.Zero(t, n, "no replay or duplicate entry after recovery")
		})
	}
}

func firstJournalCursor(t *testing.T, dir string) string {
	t.Helper()
	reader, err := sdjournal.NewJournalFromDir(dir)
	require.NoError(t, err)
	defer func() { require.NoError(t, reader.Close()) }()
	require.NoError(t, reader.SeekHead())
	n, err := reader.Next()
	require.NoError(t, err)
	require.EqualValues(t, 1, n)
	entry, err := reader.GetEntry()
	require.NoError(t, err)
	return entry.Cursor
}

func TestNativeJournalStartupReplayAndFollow(t *testing.T) {
	remote := journalRemote(t)
	for _, tc := range []struct {
		name   string
		cursor func(t *testing.T, dir string) string
		want   []string
	}{
		{"invalid cursor", func(*testing.T, string) string { return "invalid-cursor" }, []string{"record-1", "record-2", "record-3"}},
		{"foreign cursor", func(*testing.T, string) string {
			return "s=33333333333333333333333333333333;i=ffffffff;b=11111111111111111111111111111111;m=ffffffffffff;t=ffffffffffff;x=1"
		}, []string{"record-1", "record-2", "record-3"}},
		{"verified cursor", firstJournalCursor, []string{"record-2", "record-3"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			appendJournalRecords(t, remote, dir, "target.service", 1, 2, 3)
			runtime.LockOSThread()
			defer runtime.UnlockOSThread()
			tailer := testTailer(t)
			tailer.journalPath, tailer.matches = dir, []string{"_SYSTEMD_UNIT=target.service"}
			writeCursor(tailer.cursorFilePath, tc.cursor(t, dir))
			reader, err := tailer.openJournal(journalOpenModeStartup)
			require.NoError(t, err)
			defer tailer.closeJournal(reader)
			require.Equal(t, tc.want, nativeMessages(t, tailer, reader, len(tc.want)))
			require.GreaterOrEqual(t, reader.Wait(0), 0)
			appendJournalRecords(t, remote, dir, "target.service", 4)
			require.Equal(t, []string{"record-4"}, nativeMessages(t, tailer, reader, 1))
		})
	}
}

type faultyNativeReader struct {
	journalReader
	failEntry  bool
	positioned chan<- struct{}
	closes     int
}

func (r *faultyNativeReader) GetEntry() (*sdjournal.JournalEntry, error) {
	if r.failEntry {
		r.failEntry = false
		return nil, fmt.Errorf("failed to get realtime timestamp: %w", syscall.EBADMSG)
	}
	return r.journalReader.GetEntry()
}

func (r *faultyNativeReader) Previous() (uint64, error) {
	n, err := r.journalReader.Previous()
	if err == nil && r.positioned != nil {
		close(r.positioned)
		r.positioned = nil
	}
	return n, err
}

func (r *faultyNativeReader) Close() error {
	r.closes++
	return r.journalReader.Close()
}

func TestNativeJournalEntryErrorRecovery(t *testing.T) {
	remote := journalRemote(t)
	dir := t.TempDir()
	appendJournalRecords(t, remote, dir, "target.service", 1, 2, 3)
	tailer := testTailer(t)
	tailer.journalPath, tailer.matches = dir, []string{"_SYSTEMD_UNIT=target.service"}
	queue := make(chan *types.Log, 8)
	tailer.batchQueue = queue
	positioned := make(chan struct{})
	var readers []*faultyNativeReader
	tailer.readerFactory = func() (journalReader, error) {
		reader, err := sdjournal.NewJournalFromDir(dir)
		if err != nil {
			return nil, err
		}
		wrapped := &faultyNativeReader{journalReader: reader, failEntry: len(readers) == 0}
		if len(readers) > 0 {
			wrapped.positioned = positioned
		}
		readers = append(readers, wrapped)
		return wrapped, nil
	}
	ctx, cancel, done := startTestTailer(t, tailer)
	select {
	case <-positioned:
	case <-ctx.Done():
		t.Fatal("recovery did not finish positioning")
	}
	appendJournalRecords(t, remote, dir, "target.service", 4)
	require.Equal(t, "record-4", receiveTestLog(t, ctx, queue))
	cancel()
	select {
	case <-done:
	case <-time.After(3 * time.Second):
		t.Fatal("owner failed to exit")
	}
	require.Len(t, readers, 2)
	for _, reader := range readers {
		require.Equal(t, 1, reader.closes)
	}
}
